package kr.releasepilot.controlplane.analysis;
import kr.releasepilot.controlplane.release.*;import kr.releasepilot.controlplane.rollout.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import tools.jackson.databind.ObjectMapper;import java.time.*;
@Service public class AnalysisJobPlanner{
 private final RolloutStepRepository steps;private final AnalysisJobRepository jobs;private final RolloutExecutionRepository executions;private final PolicySnapshotRepository snapshots;private final ObjectMapper json;private final Clock clock;
 public AnalysisJobPlanner(RolloutStepRepository steps,AnalysisJobRepository jobs,RolloutExecutionRepository executions,PolicySnapshotRepository snapshots,ObjectMapper json,Clock clock){this.steps=steps;this.jobs=jobs;this.executions=executions;this.snapshots=snapshots;this.json=json;this.clock=clock;}
@Transactional public int planReady(){int count=0;var now=clock.instant();for(var step:steps.findByStatus(RolloutStepStatus.RUNNING)){if(step.getStartedAt()==null||now.isBefore(step.getStartedAt().plusSeconds(step.getMinimumObservationSeconds()))||jobs.existsByStepId(step.getId()))continue;var execution=executions.findById(step.getExecutionId()).orElseThrow();var snapshot=snapshots.findByReleaseId(execution.getReleaseId()).orElseThrow();try{int max=json.readTree(snapshot.getDefinition()).path("inconclusivePolicy").path("maximumAttempts").asInt(1);jobs.save(AnalysisJob.pending(step.getId(),execution.getCorrelationId(),Math.max(1,max),step.getStartedAt(),now));step.evaluating(now);count++;}catch(Exception e){throw new IllegalStateException("Cannot plan analysis job",e);}}return count;}
}
